   if(!GetClientRect(hwnd,out client)||!ClientToScreen(hwnd,ref origin))throw new InvalidOperationException("Fresh wheel client bounds required");
   double scale=GetDpiForWindow(hwnd)/96d;var clip=new System.Windows.Rect(origin.x+240*scale,origin.y+98*scale,client.right-240*scale,client.bottom-182*scale);
   if(TransportPath!=null)System.IO.File.AppendAllText(TransportPath,"wheel-anchor frame="+frame+" anchorBounds="+b+" mainClip="+clip+" scale="+scale+" expectedHWND="+hwnd.ToInt64()+" expectedPID="+ExpectedPid+Environment.NewLine);
   if(scale<=0||scale>4||b.Width<=0||b.Height<=0||!frame.Contains(b)||!clip.Contains(b))throw new InvalidOperationException("Wheel anchor must be fully inside main viewport");
   int x=(int)Math.Round(b.Left+b.Width/2),y=(int)Math.Round(b.Top+b.Height/2);POINT previous;
   if(!GetPhysicalCursorPos(out previous))throw new InvalidOperationException("Existing physical pointer guard");
   try{
    Move(x,y);System.Threading.Thread.Sleep(80);POINT physical;uint pid;
    if(!GetPhysicalCursorPos(out physical)||Math.Abs(physical.x-x)>1||Math.Abs(physical.y-y)>1||GetForegroundWindow()!=hwnd)throw new InvalidOperationException("Actual wheel pointer/foreground guard");
    var hit=WindowFromPoint(physical);var root=GetAncestor(hit,2);GetWindowThreadProcessId(root,out pid);
    if(TransportPath!=null)System.IO.File.AppendAllText(TransportPath,"wheel-beforeEmit anchor=table-search frame="+frame+" anchorBounds="+b+" mainClip="+clip+" requested="+x+","+y+" actual="+physical.x+","+physical.y+" hit="+hit.ToInt64()+" root="+root.ToInt64()+" hitPID="+pid+" expectedHWND="+hwnd.ToInt64()+" expectedPID="+ExpectedPid+" screen="+GetSystemMetrics(78)+"x"+GetSystemMetrics(79)+" dpi="+GetDpiForWindow(hwnd)+" foreground="+GetForegroundWindow().ToInt64()+Environment.NewLine);
    if(root!=hwnd||pid!=ExpectedPid)throw new InvalidOperationException("Exact owned content wheel root guard");
    var fresh=anchor.Current.BoundingRectangle;if(!fresh.Contains(physical.x,physical.y)||anchor.Current.AutomationId!="table-search"||!anchor.Current.IsEnabled||anchor.Current.IsOffscreen)throw new InvalidOperationException("Fresh unchanged wheel anchor guard");
    Emit(new INPUT{data=new UNION{mouse=new MOUSEINPUT{mouseData=unchecked((uint)(down?-240:240)),flags=0x800}}});
   }finally{if(GetForegroundWindow()==hwnd)Move(previous.x,previous.y);}
  }finally{if(old!=IntPtr.Zero)SetThreadDpiAwarenessContext(old);}
 }
 public static void Utility(string path,string operation){
  var old=SetThreadDpiAwarenessContext(new IntPtr(-4));try{
   var w=Window(path,false);SetForegroundWindow(new IntPtr(w.Current.NativeWindowHandle));System.Threading.Thread.Sleep(100);
   if(GetForegroundWindow().ToInt64()!=w.Current.NativeWindowHandle)throw new InvalidOperationException("Exact callback fixture foreground guard");
   ushort code;
   switch(operation){case "seed-stopped":code=117;break;case "seed-resize":code=118;break;case "resize":code=119;break;case "language-api":code=120;break;default:throw new InvalidOperationException("Finite callback utility only");}
   Key(code);
  }finally{if(old!=IntPtr.Zero)SetThreadDpiAwarenessContext(old);}
 }
 public static void ReplaceQuery(string path,string id,string value){
  if(id!="table-search"&&id!="MatchingDialog-search"&&id!="source-host")throw new InvalidOperationException("Literal callback editor required");
  if(id=="source-host"?value!="":value!=""&&value!="orders"&&value!="archive")throw new InvalidOperationException("Synthetic callback query only");
  var old=SetThreadDpiAwarenessContext(new IntPtr(-4));try{
   var w=Window(path,false);var focus=AutomationElement.FocusedElement;
   if(focus==null||focus.Current.ProcessId!=w.Current.ProcessId||focus.Current.ControlType!=ControlType.Edit||focus.Current.AutomationId!=id||GetForegroundWindow().ToInt64()!=w.Current.NativeWindowHandle)throw new InvalidOperationException("Existing exact query editor focus required");
   bool ctrl=false;try{Emit(new INPUT{type=1,data=new UNION{key=new KEYBDINPUT{vk=17}}});ctrl=true;Key(65);}finally{if(ctrl)Emit(new INPUT{type=1,data=new UNION{key=new KEYBDINPUT{vk=17,flags=2}}});}
   Key(8);foreach(char c in value){bool down=false;try{Emit(new INPUT{type=1,data=new UNION{key=new KEYBDINPUT{scan=c,flags=4}}});down=true;}finally{if(down)Emit(new INPUT{type=1,data=new UNION{key=new KEYBDINPUT{scan=c,flags=6}}});}}
  }finally{if(old!=IntPtr.Zero)SetThreadDpiAwarenessContext(old);}
 }

